  /* Digits of equal width so the times and heights line up in columns. */
  font-variant-numeric: tabular-nums;
}

th,
td {
  padding: 10px 0;
  text-align: left;
  font-weight: 400;
  border-bottom: 1px solid #d5dcdf;
}

tbody tr:last-child td {
  border-bottom: 0;
}

th {
  padding-top: 0;
  font-size: 13px;
  color: #4d585e;
}

td:first-child {
  color: #4d585e;
}

/* The time is the number people come for, so it carries the weight. */
td:nth-child(2) {
  font-weight: 500;
}

th:last-child,
td:last-child {
  text-align: right;
}

/* Three features in a row, each under a thin rule. */
.points {
  row-gap: 32px;
  padding-bottom: 96px;
}

.point {
  padding-top: 20px;
  border-top: 1px solid #d5dcdf;
}

.point h3 {
  margin: 0 0 6px;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.3;
}

.point p {
  margin: 0;
  color: #4d585e;
}

/* Tablet and below: one column. The sample table goes under the pitch,
   and the features stack so each line keeps a readable length. */
@media (max-width: 860px) {
  .hero,
  .points {
    grid-template-columns: minmax(0, 1fr);
  }

  .hero {
    padding-top: 48px;
    padding-bottom: 64px;
  }

  .hero-text,
  .today {
    grid-column: auto;
  }

  .hero-text,
  .today,
  .point {
    max-width: 560px;
  }
}

/* Phone: one column for everything and narrower side margins. */
@media (max-width: 600px) {
  .site-header,
  .hero,
  .points {
    padding-left: 20px;
    padding-right: 20px;
  }

  .site-header {
    padding-top: 16px;
    padding-bottom: 16px;
  }

  .site-nav {
    gap: 4px 20px;
  }

  h1 {
    font-size: 28px;
  }

  .hero {
    padding-top: 32px;
    padding-bottom: 48px;
    gap: 36px;
  }

  .today {
    padding: 20px;
  }

  .points {
    grid-template-columns: minmax(0, 1fr);
    gap: 32px;
    padding-bottom: 64px;
  }
}

