@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

/* One width and one side margin for every band, so all left edges line up. */
.site-header,
.hero,
.points {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 64px;
  padding-right: 64px;
}

.site-header {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 8px 28px;
  padding-top: 22px;
  padding-bottom: 22px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 28px;
}

.site-nav a {
  text-decoration: none;
  color: #4d585e;
}

/* Hero and feature row share one three-column grid, so their edges line up.
   In the hero the pitch spans two columns and the sample tides take the third. */
.hero,
.points {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 48px;
}

.hero {
  row-gap: 48px;
  align-items: center;
  padding-top: 72px;
  padding-bottom: 88px;
}

.hero-text {
  grid-column: 1 / span 2;
  max-width: 520px;
}

.today {
  grid-column: 3;
}

h1 {
  margin: 0 0 16px;
  font-size: 34px;
  font-weight: 500;
  line-height: 1.2;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.today {
  padding: 24px;
  border: 1px solid #d5dcdf;
  border-radius: 6px;
  background: #f4f7f8;
}

h2 {
  margin: 0 0 12px;
  font-size: 19px;
  font-weight: 500;
  line-height: 1.3;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 17px;
  /* Digits of equal width so the times and heights line up in columns. */
  font-variant-numeric: tabular-nums;
}

th,
td {
  padding: 10px 0;
  text-align: left;
  font-weight: 400;
  border-bottom: 1px solid #d5dcdf;
